INSERT INTO `music_song` VALUES (41, '广东歌 Minimix 10 [王菲/张立基/关淑怡/叶倩文/郑秀文/林忆莲/谭咏麟/张学友/许志安/黎明诗/吴国敬/郭富城/梅艳芳/彭羚/软硬天师 ]', 'Leon Megamix', NULL, 'cantopop', NULL, 763246, 'Feel free to listen, share, and stream on your favorite places!\nPlease subscribe to this channel and enjoy the latest release:\n✨  Facebook - https://www.facebook.com/djleon.megamix\n✨  Download - https://soundcloud.com/djleonmix2015\n✨  Podcast - https://djleonmix.podbean.com/\n\n广东歌 Minimix\n王菲 – 讨好自己\n张立基 - 妳走了\n关淑怡 - 恋一世的爱\n叶倩文 郑秀文 - 谈情说爱\n林忆莲 - 前尘\n谭咏麟 – 离别心曲\n王菲 - 天使\n张学友 - Linda\n许志安 – 雨后阳光\n许志安 - 不倦的蝴蝶\n黎明诗 - 心意\n关淑怡 - 众生花\n王菲 - 诱惑我\n吴国敬 - 聊斋 - 醉\n郭富城 - 复制灵魂\n梅艳芳 - 夜蛇\n彭羚 - 舍得听我吗\n软硬天师，王菲 - 请勿客气\n关淑怡 - 他需要你，她需要你', 'track', 'all-rights-reserved', 'minimix-10', 'https://soundcloud.com/djleonmix2015/minimix-10', 'https://i1.sndcdn.com/artworks-y7bOT3BOXph7yEkN-vxrVWQ-large.jpg', NULL, NULL, 763246, 4, 66, 'megamix');
