INSERT INTO `music_song` VALUES (74, '一千个伤心的理由-张学友', 'Shen Yang', NULL, '', NULL, 276270, '曲：李思菘 词：邢增华\r\n\r\n爱过的人 我已不再拥有\r\n许多故事有伤心的理由\r\n这一次我的爱情\r\n等不到天长地久\r\n错过的人 是否可以回首\r\n爱过的心没有任何请求\r\n许多故事有伤心的理由\r\n这一次我的爱情\r\n等不到天长地久\r\n走过的路 再也不能停留\r\n一千个伤心的理由\r\n一千个伤心的理由\r\n最后我的爱情在故事里慢慢陈旧\r\n一千个伤心的理由\r\n一千个伤心的理由\r\n最后在别人的故事里我被遗忘', 'track', 'all-rights-reserved', 'tfm14o7fidnk', 'https://soundcloud.com/shen-yang/tfm14o7fidnk', 'https://i1.sndcdn.com/artworks-000042022816-7dc1py-large.jpg', NULL, NULL, 276270, 10, 2943, 'soundcloud:source=web-record');
