INSERT INTO `music_song` VALUES (102, '张学友 - 楼上来的声音 (cover)', 'Yiufai Lin', NULL, '', NULL, 256231, '工作不顺心的时候，我们用爱情来平复自己。\r\n爱情不如意的时候，我们用工作来麻醉自己。\r\n没有什麽事情是可以如你想象般完美。。。\r\n不如静下心来，不为讨好众人，听一听楼上来的声音。。。什麽声音，都好。', 'track', 'all-rights-reserved', 'hkrgurqtdsf3', 'https://soundcloud.com/yiufai-lin/hkrgurqtdsf3', 'https://i1.sndcdn.com/artworks-000032028622-l9z2k7-large.jpg', NULL, NULL, 256231, 24, 2648, 'soundcloud:source=iphone-record');
