INSERT INTO `music_song` VALUES (126, 'Avaz Shodi (feat The Don)', '', '', 'Pop', NULL, 209671, 'Ali Yasini & The Don - Avaz Shodi | ORIGINAL AUDIO \n\n\nListen On YT Music: http://bit.ly/3rUwKMi\nListen On Spotify: http://spoti.fi/3rUwQDE\nGet On iTunes/AppleMusic: http://apple.co/3dekZMK\n\n\n►Follow Ali Yasini Online: \nSubscribe: http://bit.ly/3piQBDh\nInstagram: https://bit.ly/2LQJ0hK\nTelegram: http://bit.ly/3tVfnwJ\n\n\n►Follow Lima Records Online: \nWebsite: http://limaconcert.com/\nSubscribe: http://bit.ly/2MyBp80\nInstagram: https://bit.ly/39WqY6V\n\nPersian Lyrics:\nیه تیکه بودی از تنم\nبهش چجوری گند زدن\nببین برعکس تو منو به گذشته زوری بستنم\nقبلنا با اراده تر بودم\nمیومد اسمت نمیزدم تنها از خونه بیرون از حرصت\nبودیم معروف ترین عشق میون قصه ها \nچقدر گفتم دیگه نمیاد دیوونه مثلت\nقبلنا عکسامون بود همه به دیوارو\nهیچ جایی ندیدم اون خنده یه زیبارو \nنمیشنید شکستن بغضمو کسی\nاشکامو ندیدن تو جمع رفیقامو\nقبلنا با تو چقدر آرزوهام فرق داشت\nاز اولی تا اخریش بودی تو همراش \nکنار هم بودیم یه دنیا نبود حریفمون\nقسم میخوردن عشقمونو کل شهر پاش\nالانم که تنها بغض قلب منی\nمنتظرم یه موقع زنگ بزنی\nحیف که نشد تو هم بفهمی نقطه ضعف منی\n\nیه تیکه بودی از تنم\nبهش چجوری گند زدن\nببین برعکس تو منو به گذشته زوری بستنم\n\nتو عوض شدی از تو چشات میشه دید\nاگه قراره تو ببری من میزنم زیر میز\nافتادم رو دور فراموش کردنت رو شیب تیز\nولی دلم میکشونه بالا منو سینه خیز\nالان که دادی به همه چی عادتم \nحقته حقته هرچی که سرت بیاد اصن\nیکاری کن شاید بشه یادم بری فقط\nبیا زل بزن تو چشام بگو بدت میاد ازم چون\nدیگه خسته شدم من از این\nوضعیت شدیم تو خاطرات بدِ هم اسیر\nهم مقصدمون اشتباه بودش و هم مسیر\nتو منو گرفتی عوضی !\nمن اونی نیستم که بذاری سر به سرم\nخودم بدتر از تو از همیشه خسته ترم\nفکر میکنم چی میشی بعد من از یه طرف\nجا ندارم بندازی روی این قلبه ترک\n\n#aliyasini  \n#MageChandBarZendam?!', NULL, NULL, 'avaz-shodi', 'https://soundcloud.com/yasiniali/avaz-shodi', 'https://i1.sndcdn.com/artworks-8QJlkcFv2rwrFPQH-ydcrPw-{size}.jpg', NULL, NULL, 209711, 11766, 560025, 'Ali Yasini, Avaz Shodi, The Don, pop');
